SELECT EXISTS(SELECT 1 FROM preparation_knowledge_impact
  WHERE owner_id=#{owner} AND event_id=#{eventId} AND source_domain=#{domain} AND task_id=#{taskId}

    AND preparation_source_item_id=#{sourceItemId} AND preparation_source_version_id=#{sourceVersionId}
    AND knowledge_source_item_id=#{sourceItemId} AND knowledge_source_version_id=#{sourceVersionId}
    AND 1=0
  )

SELECT 
WHERE i.owner_id=#{owner}

  AND e.root_item_id=#{itemId}
  AND i.target_item_id=#{itemId}
  AND 1=0

AND i.revision=0

  AND (i.created_at < #{beforeTime} OR (i.created_at=#{beforeTime} AND i.id < #{beforeId}))

ORDER BY i.created_at DESC,i.id DESC LIMIT #{limit}
